import React, { useState, useEffect } from 'react';
import MatchDetailsModal from './MatchDetailsModal';

function MatchingView({ clients, properties }) {
  const [selectedClientId, setSelectedClientId] = useState(clients[0]?.id || '');
  const [matches, setMatches] = useState([]);
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [showModal, setShowModal] = useState(false);

  const calculateMatch = (client, property) => {
    if (!client || !property || property.availability !== 'متاحة') return 0;

    let score = 0;
    // Location (40%)
    if (property.location.city.includes(client.preferredLocation) || property.location.neighborhood.includes(client.preferredLocation)) {
      score += 40;
    }
    // Type & Status (25%)
    const statusMap = { 'شراء': 'للبيع', 'إيجار': 'للإيجار' };
    if (property.type === client.desiredType && property.status === statusMap[client.desiredStatus]) {
      score += 25;
    }
    // Budget (20%)
    if (property.price <= client.budget) {
      score += 20;
    }
    // Area & Rooms (15%)
    if (property.area >= client.minArea && property.rooms >= client.minRooms) {
      score += 15;
    }

    return score;
  };

  useEffect(() => {
    if (!selectedClientId) {
      setMatches([]);
      return;
    }
    const currentClient = clients.find(c => c.id === parseInt(selectedClientId));
    const calculatedMatches = properties
      .map(prop => ({
        ...prop,
        matchPercentage: calculateMatch(currentClient, prop),
      }))
      .filter(prop => prop.matchPercentage > 0)
      .sort((a, b) => b.matchPercentage - a.matchPercentage);

    setMatches(calculatedMatches);
  }, [selectedClientId, clients, properties]);

  const exportCSV = () => {
    if (!matches || matches.length === 0) return;
    const headers = ['id','type','status','city','neighborhood','price','area','rooms','matchPercentage','description'];
    const rows = matches.map(m => [m.id,m.type,m.status,m.location.city,m.location.neighborhood,m.price,m.area,m.rooms,m.matchPercentage,m.description]);
    const csv = [headers.join(','), ...rows.map(r => r.map(cell=>`"${String(cell).replace(/"/g,'""')}"`).join(','))].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `matches_${selectedClientId || 'all'}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div>
      <h2 className="mb-4">🎯 التطابق الذكي</h2>
      <div className="card shadow-sm mb-4">
        <div className="card-body">
          <div className="row align-items-end">
            <div className="col-md-4">
              <label htmlFor="client-select" className="form-label fw-bold">اختر العميل:</label>
              <select 
                id="client-select" 
                className="form-select" 
                value={selectedClientId} 
                onChange={e => setSelectedClientId(e.target.value)}
              >
                <option value="" disabled>-- اختر عميل --</option>
                {clients.map(client => (
                  <option key={client.id} value={client.id}>{client.name} - {client.desiredType} في {client.preferredLocation}</option>
                ))}
              </select>
            </div>
            <div className="col-md-4 text-end">
              <button className="btn btn-outline-primary btn-sm" onClick={exportCSV}>تصدير CSV</button>
            </div>
          </div>
        </div>
      </div>

      {selectedClientId && (
        <div>
          <h4 className="mb-3">نتائج المطابقة:</h4>
          {matches.length > 0 ? (
            <div className="list-group">
              {matches.map(prop => (
                <div key={prop.id} className="list-group-item list-group-item-action d-flex justify-content-between align-items-center" style={{cursor:'pointer'}} onClick={() => { setSelectedMatch(prop); setShowModal(true); }}>
                  <div>
                    <h5 className="mb-1">{prop.type} في {prop.location.neighborhood}</h5>
                    <p className="mb-1">{prop.description}</p>
                    <small>💰 السعر: {prop.price.toLocaleString()} جنيه | 📏 المساحة: {prop.area} م²</small>
                  </div>
                  <span 
                    className={`badge rounded-pill matching-badge ${prop.matchPercentage >= 75 ? 'bg-success' : prop.matchPercentage >= 50 ? 'bg-warning text-dark' : 'bg-secondary'}`}>
                    {prop.matchPercentage}%
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <div className="alert alert-warning text-center" role="alert">
              😕 لا توجد عقارات مطابقة لهذا الطلب حاليًا.
            </div>
          )}
        </div>
      )}

      {/* Match details modal */}
      <MatchDetailsModal
        show={showModal}
        onClose={() => { setShowModal(false); setSelectedMatch(null); }}
        property={selectedMatch}
        client={clients.find(c => c.id === parseInt(selectedClientId))}
      />
    </div>
  );
}

export default MatchingView;
